// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address player) public {
        vm.assume(player != address(0));
        vm.assume(player != address(this));

        uint256 ticket = 10;
        vm.deal(player, ticket);

        uint256 potBefore = c.pot();

        vm.prank(player);
        c.play{value: ticket}();

        assertTrue(c.pot() == potBefore + ticket);
    }
}
